package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.EnumResolver;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.math.*;
import java.net.URI;
import java.net.URL;
import java.util.*;
import java.util.Calendar;
import java.util.Currency;
import java.util.Date;
import java.util.Locale;
import java.util.UUID;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StdKeyDeserializer_forType_TriageGen0Test {

    @Test
    public void testForType_StringAndObject() {
        // Testing String.class branch
        StdKeyDeserializer stringDeser = StdKeyDeserializer.forType(String.class);
        assertNotNull(stringDeser);
        assertEquals(String.class, stringDeser.getKeyClass());

        // Testing Object.class branch
        StdKeyDeserializer objectDeser = StdKeyDeserializer.forType(Object.class);
        assertNotNull(objectDeser);
        assertEquals(Object.class, objectDeser.getKeyClass());
    }

    @Test
    public void testForType_CommonTypes() {
        // UUID
        StdKeyDeserializer uuidDeser = StdKeyDeserializer.forType(UUID.class);
        assertNotNull(uuidDeser);
        assertEquals(UUID.class, uuidDeser.getKeyClass());

        // Integer
        StdKeyDeserializer intDeser = StdKeyDeserializer.forType(Integer.class);
        assertNotNull(intDeser);
        assertEquals(Integer.class, intDeser.getKeyClass());

        // Long
        StdKeyDeserializer longDeser = StdKeyDeserializer.forType(Long.class);
        assertNotNull(longDeser);
        assertEquals(Long.class, longDeser.getKeyClass());

        // Date
        StdKeyDeserializer dateDeser = StdKeyDeserializer.forType(Date.class);
        assertNotNull(dateDeser);
        assertEquals(Date.class, dateDeser.getKeyClass());

        // Calendar
        StdKeyDeserializer calDeser = StdKeyDeserializer.forType(Calendar.class);
        assertNotNull(calDeser);
        assertEquals(Calendar.class, calDeser.getKeyClass());
    }

    @Test
    public void testForType_LessCommonTypes() {
        // Boolean
        StdKeyDeserializer boolDeser = StdKeyDeserializer.forType(Boolean.class);
        assertNotNull(boolDeser);
        assertEquals(Boolean.class, boolDeser.getKeyClass());

        // Byte
        StdKeyDeserializer byteDeser = StdKeyDeserializer.forType(Byte.class);
        assertNotNull(byteDeser);
        assertEquals(Byte.class, byteDeser.getKeyClass());

        // Character
        StdKeyDeserializer charDeser = StdKeyDeserializer.forType(Character.class);
        assertNotNull(charDeser);
        assertEquals(Character.class, charDeser.getKeyClass());

        // Short
        StdKeyDeserializer shortDeser = StdKeyDeserializer.forType(Short.class);
        assertNotNull(shortDeser);
        assertEquals(Short.class, shortDeser.getKeyClass());

        // Float
        StdKeyDeserializer floatDeser = StdKeyDeserializer.forType(Float.class);
        assertNotNull(floatDeser);
        assertEquals(Float.class, floatDeser.getKeyClass());

        // Double
        StdKeyDeserializer doubleDeser = StdKeyDeserializer.forType(Double.class);
        assertNotNull(doubleDeser);
        assertEquals(Double.class, doubleDeser.getKeyClass());

        // URI
        StdKeyDeserializer uriDeser = StdKeyDeserializer.forType(URI.class);
        assertNotNull(uriDeser);
        assertEquals(URI.class, uriDeser.getKeyClass());

        // URL
        StdKeyDeserializer urlDeser = StdKeyDeserializer.forType(URL.class);
        assertNotNull(urlDeser);
        assertEquals(URL.class, urlDeser.getKeyClass());

        // Class
        StdKeyDeserializer classDeser = StdKeyDeserializer.forType(Class.class);
        assertNotNull(classDeser);
        assertEquals(Class.class, classDeser.getKeyClass());
    }

    @Test
    public void testForType_WithFromStringDeserializer() {
        // Locale (Uses FromStringDeserializer branch)
        StdKeyDeserializer localeDeser = StdKeyDeserializer.forType(Locale.class);
        assertNotNull(localeDeser);
        assertEquals(Locale.class, localeDeser.getKeyClass());

        // Currency (Uses FromStringDeserializer branch)
        StdKeyDeserializer currencyDeser = StdKeyDeserializer.forType(Currency.class);
        assertNotNull(currencyDeser);
        assertEquals(Currency.class, currencyDeser.getKeyClass());
    }

    @Test
    public void testForType_UnknownType() {
        // Testing the 'else' branch that returns null
        StdKeyDeserializer unknownDeser = StdKeyDeserializer.forType(Double.class.getClass().getEnclosingClass()); 
        // Using a class that is not in the list, e.g., a custom class or an array type
        StdKeyDeserializer nullDeser = StdKeyDeserializer.forType(int[].class);
        assertNull(nullDeser);
    }
}
